export interface ConnectorConfig {
  /** Mailchimp API key (format: {key}-{datacenter}, e.g., abc123-us1) */
  mailchimpApiKey: string
  /** Mailchimp audience/list ID */
  listId: string
  /** Optional injected fetch for testing */
  fetch?: typeof fetch
}

export interface StripeWebhookPayload {
  id: string
  object: string
  api_version: string
  created: number
  data: {
    object: StripeCheckoutSession
  }
  livemode: boolean
  pending_webhooks: number
  request: {
    id: string | null
    idempotency_key: string | null
  }
  type: string
}

export interface StripeCheckoutSession {
  id: string
  object: string
  customer: string | StripeCustomer
  customer_email: string | null
  mode: string
  setup_intent: string | null
  subscription: string | StripeSubscription | null
  success_url: string
}

export interface StripeCustomer {
  id: string
  object: string
  email: string | null
  subscriptions?: {
    object: string
    data: StripeSubscription[]
    has_more: boolean
    total_count: number
    url: string
  }
}

export interface StripeSubscription {
  id: string
  object: string
  plan: StripePlan
  status: string
  customer: string
}

export interface StripePlan {
  id: string
  object: string
  nickname: string | null
  active: boolean
}

export interface HandleResult {
  mailchimpContactId: string
  email: string
  tags: string[]
}

function extractDatacenter(apiKey: string): string {
  const parts = apiKey.split('-')
  if (parts.length < 2) {
    throw new Error('Invalid Mailchimp API key format: expected {key}-{datacenter}')
  }
  return parts.slice(1).join('-')
}

function validatePayload(payload: StripeWebhookPayload): void {
  if (!payload.data?.object) {
    throw new Error('Missing data.object in webhook payload')
  }
  const session = payload.data.object
  if (!session.customer || typeof session.customer === 'string') {
    throw new Error('Customer object not expanded in webhook payload. Create the Checkout Session with expand=[\"customer\", \"subscription\"]')
  }
  const customer = session.customer as StripeCustomer
  if (!customer.email) {
    throw new Error('Customer email is missing. Ensure customer_email is provided when creating the Checkout Session or customer is expanded with email')
  }
  if (!customer.subscriptions?.data?.length) {
    throw new Error('No subscriptions found on customer. Ensure subscription is expanded when creating the Checkout Session')
  }
  const subscription = customer.subscriptions.data[0]
  if (!subscription.plan?.id) {
    throw new Error('Subscription plan ID is missing')
  }
}

export async function handle(
  payload: StripeWebhookPayload,
  config: ConnectorConfig
): Promise<HandleResult> {
  const fetchImpl = config.fetch ?? fetch
  validatePayload(payload)

  const session = payload.data.object
  const customer = session.customer as StripeCustomer
  const subscription = customer.subscriptions!.data[0]
  const plan = subscription.plan

  const email = customer.email!
  const tag = plan.nickname ?? plan.id

  const datacenter = extractDatacenter(config.mailchimpApiKey)
  const url = `https://${datacenter}.api.mailchimp.com/3.0/lists/${config.listId}/contacts`

  const body = {
    email_address: email,
    tags: [tag]
  }

  const response = await fetchImpl(url, {
    method: 'POST',
    headers: {
      'Authorization': `Bearer ${config.mailchimpApiKey}`,
      'Content-Type': 'application/json'
    },
    body: JSON.stringify(body)
  })

  if (!response.ok) {
    throw new Error(`Mailchimp API error: ${response.status} ${response.statusText} at POST ${url}`)
  }

  const result = await response.json() as { id: string; email_address: string; tags: Array<{ id: string; name: string }> }

  return {
    mailchimpContactId: result.id,
    email: result.email_address,
    tags: result.tags.map(t => t.name)
  }
}

import { describe, it, expect, vi } from 'vitest'
import { handle, ConnectorConfig, StripeWebhookPayload } from './connector'
import { SOURCE_EXAMPLE, contractFetch, fakeFetch, jsonResponse, TARGET_ENDPOINTS } from './fixtures'

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch()
    const config: ConnectorConfig = {
      mailchimpApiKey: 'testkey-us1',
      listId: 'list_123',
      fetch
    }
    // The SOURCE_EXAMPLE lacks expanded customer/subscription data, so we expect a validation error
    await expect(handle(SOURCE_EXAMPLE as unknown as StripeWebhookPayload, config)).rejects.toThrow(
      'Customer object not expanded in webhook payload'
    )
    expect(calls.length).toBe(0)
  })
})

describe('handle', () => {
  const baseConfig: ConnectorConfig = {
    mailchimpApiKey: 'abc123-us1',
    listId: 'list_456'
  }

  const createValidPayload = (overrides: Partial<StripeWebhookPayload> = {}): StripeWebhookPayload => ({
    id: 'evt_test',
    object: 'event',
    api_version: '2019-03-14',
    created: 1561420781,
    data: {
      object: {
        id: 'cs_test',
        object: 'checkout.session',
        customer: {
          id: 'cus_test',
          object: 'customer',
          email: 'customer@example.com',
          subscriptions: {
            object: 'list',
            data: [{
              id: 'sub_test',
              object: 'subscription',
              plan: {
                id: 'plan_monthly',
                object: 'plan',
                nickname: 'Monthly Plan',
                active: true
              },
              status: 'active',
              customer: 'cus_test'
            }],
            has_more: false,
            total_count: 1,
            url: '/v1/customers/cus_test/subscriptions'
          }
        },
        customer_email: 'customer@example.com',
        mode: 'subscription',
        setup_intent: null,
        subscription: 'sub_test',
        success_url: 'https://example.com/success'
      }
    },
    livemode: false,
    pending_webhooks: 1,
    request: { id: null, idempotency_key: null },
    type: 'checkout.session.completed',
    ...overrides
  })

  it('successfully adds subscriber with plan nickname as tag', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      expect(req.method).toBe('POST')
      expect(req.url).toBe('https://us1.api.mailchimp.com/3.0/lists/list_456/contacts')
      expect(req.headers.get('authorization')).toBe('Bearer abc123-us1')
      expect(req.json).toEqual({
        email_address: 'customer@example.com',
        tags: ['Monthly Plan']
      })
      return jsonResponse({
        id: 'contact_789',
        email_address: 'customer@example.com',
        tags: [{ id: 'tag_1', name: 'Monthly Plan' }]
      }, 201)
    })

    const payload = createValidPayload()
    const result = await handle(payload, { ...baseConfig, fetch })

    expect(result).toEqual({
      mailchimpContactId: 'contact_789',
      email: 'customer@example.com',
      tags: ['Monthly Plan']
    })
    expect(calls).toHaveLength(1)
  })

  it('uses plan ID as tag when nickname is null', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      expect(req.json).toEqual({
        email_address: 'customer@example.com',
        tags: ['plan_monthly']
      })
      return jsonResponse({
        id: 'contact_789',
        email_address: 'customer@example.com',
        tags: [{ id: 'tag_1', name: 'plan_monthly' }]
      }, 201)
    })

    const payload = createValidPayload({
      data: {
        object: {
          ...createValidPayload().data.object,
          customer: {
            ...createValidPayload().data.object.customer,
            subscriptions: {
              ...(createValidPayload().data.object.customer as any).subscriptions,
              data: [{
                ...(createValidPayload().data.object.customer as any).subscriptions.data[0],
                plan: {
                  id: 'plan_monthly',
                  object: 'plan',
                  nickname: null,
                  active: true
                }
              }]
            }
          }
        }
      }
    })

    const result = await handle(payload, { ...baseConfig, fetch })

    expect(result.tags).toEqual(['plan_monthly'])
    expect(calls).toHaveLength(1)
  })

  it('throws when customer object is not expanded', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse({}, 200))
    const payload = createValidPayload({
      data: {
        object: {
          ...createValidPayload().data.object,
          customer: 'cus_test' // string instead of expanded object
        }
      }
    })

    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow(
      'Customer object not expanded in webhook payload'
    )
    expect(calls).toHaveLength(0)
  })

  it('throws when customer email is missing', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse({}, 200))
    const payload = createValidPayload({
      data: {
        object: {
          ...createValidPayload().data.object,
          customer: {
            ...createValidPayload().data.object.customer,
            email: null
          }
        }
      }
    })

    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow(
      'Customer email is missing'
    )
    expect(calls).toHaveLength(0)
  })

  it('throws when subscriptions data is missing', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse({}, 200))
    const payload = createValidPayload({
      data: {
        object: {
          ...createValidPayload().data.object,
          customer: {
            ...createValidPayload().data.object.customer,
            subscriptions: { object: 'list', data: [], has_more: false, total_count: 0, url: '' }
          }
        }
      }
    })

    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow(
      'No subscriptions found on customer'
    )
    expect(calls).toHaveLength(0)
  })

  it('throws when plan ID is missing', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse({}, 200))
    const payload = createValidPayload({
      data: {
        object: {
          ...createValidPayload().data.object,
          customer: {
            ...createValidPayload().data.object.customer,
            subscriptions: {
              ...(createValidPayload().data.object.customer as any).subscriptions,
              data: [{
                ...(createValidPayload().data.object.customer as any).subscriptions.data[0],
                plan: { id: '', object: 'plan', nickname: 'Test', active: true }
              }]
            }
          }
        }
      }
    })

    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow(
      'Subscription plan ID is missing'
    )
    expect(calls).toHaveLength(0)
  })

  it('throws on non-2xx response from Mailchimp', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse({ detail: 'Invalid API key' }, 401))

    const payload = createValidPayload()
    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow(
      'Mailchimp API error: 401 Unauthorized at POST https://us1.api.mailchimp.com/3.0/lists/list_456/contacts'
    )
    expect(calls).toHaveLength(1)
  })

  it('derives datacenter from API key correctly', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      expect(req.url).toBe('https://us10.api.mailchimp.com/3.0/lists/list_456/contacts')
      return jsonResponse({ id: 'c1', email_address: 'x@y.z', tags: [{ id: 't1', name: 't' }] }, 201)
    })

    const payload = createValidPayload()
    await handle(payload, { ...baseConfig, mailchimpApiKey: 'key-us10', fetch })
    expect(calls).toHaveLength(1)
  })

  it('throws on invalid API key format', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse({}, 200))
    const payload = createValidPayload()

    await expect(handle(payload, { ...baseConfig, mailchimpApiKey: 'invalidkey', fetch })).rejects.toThrow(
      'Invalid Mailchimp API key format'
    )
    expect(calls).toHaveLength(0)
  })
})

