    )
    expect(calls.length).toBe(0)
  })
})

describe('handle', () => {
  const baseConfig: ConnectorConfig = {
    mailchimpApiKey: 'abc123-us1',
    listId: 'list_456'
  }

  const createValidPayload = (overrides: Partial<StripeWebhookPayload> = {}): StripeWebhookPayload => ({
    id: 'evt_test',
    object: 'event',
    api_version: '2019-03-14',
    created: 1561420781,
    data: {
      object: {
        id: 'cs_test',
        object: 'checkout.session',
        customer: {
          id: 'cus_test',
          object: 'customer',
          email: 'customer@example.com',
          subscriptions: {
            object: 'list',
            data: [{
              id: 'sub_test',
              object: 'subscription',
              plan: {
                id: 'plan_monthly',
                object: 'plan',
                nickname: 'Monthly Plan',
                active: true
              },
              status: 'active',
              customer: 'cus_test'
            }],
            has_more: false,
            total_count: 1,
            url: '/v1/customers/cus_test/subscriptions'
          }
        },
        customer_email: 'customer@example.com',
        mode: 'subscription',
        setup_intent: null,
        subscription: 'sub_test',
        success_url: 'https://example.com/success'
      }
    },
    livemode: false,
    pending_webhooks: 1,
    request: { id: null, idempotency_key: null },
    type: 'checkout.session.completed',
    ...overrides
  })

  it('successfully adds subscriber with plan nickname as tag', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      expect(req.method).toBe('POST')
      expect(req.url).toBe('https://us1.api.mailchimp.com/3.0/lists/list_456/contacts')
      expect(req.headers.get('authorization')).toBe('Bearer abc123-us1')
      expect(req.json).toEqual({
        email_address: 'customer@example.com',
        tags: ['Monthly Plan']
      })
      return jsonResponse({
        id: 'contact_789',
        email_address: 'customer@example.com',
        tags: [{ id: 'tag_1', name: 'Monthly Plan' }]
      }, 201)
    })

    const payload = createValidPayload()
    const result = await handle(payload, { ...baseConfig, fetch })

    expect(result).toEqual({
      mailchimpContactId: 'contact_789',
      email: 'customer@example.com',
      tags: ['Monthly Plan']
    })
    expect(calls).toHaveLength(1)
  })

  it('uses plan ID as tag when nickname is null', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      expect(req.json).toEqual({
        email_address: 'customer@example.com',
        tags: ['plan_monthly']
      })
      return jsonResponse({
        id: 'contact_789',
        email_address: 'customer@example.com',
        tags: [{ id: 'tag_1', name: 'plan_monthly' }]
      }, 201)
    })

    const payload = createValidPayload({
      data: {
        object: {
          ...createValidPayload().data.object,
          customer: {
            ...createValidPayload().data.object.customer,
            subscriptions: {
              ...(createValidPayload().data.object.customer as any).subscriptions,
              data: [{
                ...(createValidPayload().data.object.customer as any).subscriptions.data[0],
                plan: {
                  id: 'plan_monthly',
                  object: 'plan',
                  nickname: null,
                  active: true
                }
              }]
            }
          }
        }
      }
    })

    const result = await handle(payload, { ...baseConfig, fetch })

    expect(result.tags).toEqual(['plan_monthly'])
    expect(calls).toHaveLength(1)
  })

  it('throws when customer object is not expanded', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse({}, 200))
    const payload = createValidPayload({
      data: {
        object: {
          ...createValidPayload().data.object,
          customer: 'cus_test' // string instead of expanded object
        }
      }
    })

    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow(
      'Customer object not expanded in webhook payload'
    )
    expect(calls).toHaveLength(0)
  })

  it('throws when customer email is missing', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse({}, 200))
    const payload = createValidPayload({
      data: {
        object: {
          ...createValidPayload().data.object,
          customer: {
            ...createValidPayload().data.object.customer,
            email: null
          }
        }
      }
    })

    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow(
      'Customer email is missing'
    )
    expect(calls).toHaveLength(0)
  })

  it('throws when subscriptions data is missing', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse({}, 200))
    const payload = createValidPayload({
      data: {
        object: {
          ...createValidPayload().data.object,
          customer: {
            ...createValidPayload().data.object.customer,
            subscriptions: { object: 'list', data: [], has_more: false, total_count: 0, url: '' }
          }
        }
      }
    })

    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow(
      'No subscriptions found on customer'
    )
    expect(calls).toHaveLength(0)
  })

  it('throws when plan ID is missing', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse({}, 200))
    const payload = createValidPayload({
      data: {
        object: {
          ...createValidPayload().data.object,
          customer: {
            ...createValidPayload().data.object.customer,
            subscriptions: {
              ...(createValidPayload().data.object.customer as any).subscriptions,
              data: [{
                ...(createValidPayload().data.object.customer as any).subscriptions.data[0],
                plan: { id: '', object: 'plan', nickname: 'Test', active: true }
              }]
            }
          }
        }
      }
    })

    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow(
      'Subscription plan ID is missing'
    )
    expect(calls).toHaveLength(0)
  })

  it('throws on non-2xx response from Mailchimp', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse({ detail: 'Invalid API key' }, 401))

    const payload = createValidPayload()
    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow(
      'Mailchimp API error: 401 Unauthorized at POST https://us1.api.mailchimp.com/3.0/lists/list_456/contacts'
    )
    expect(calls).toHaveLength(1)
  })

  it('derives datacenter from API key correctly', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      expect(req.url).toBe('https://us10.api.mailchimp.com/3.0/lists/list_456/contacts')
      return jsonResponse({ id: 'c1', email_address: 'x@y.z', tags: [{ id: 't1', name: 't' }] }, 201)
    })

    const payload = createValidPayload()
    await handle(payload, { ...baseConfig, mailchimpApiKey: 'key-us10', fetch })
    expect(calls).toHaveLength(1)
  })

  it('throws on invalid API key format', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse({}, 200))
    const payload = createValidPayload()

    await expect(handle(payload, { ...baseConfig, mailchimpApiKey: 'invalidkey', fetch })).rejects.toThrow(
      'Invalid Mailchimp API key format'
    )
    expect(calls).toHaveLength(0)
  })
})

